        Bundle state(){Bundle saved=new Bundle();saved.putString("title",title);saved.putLong("initial",initial);saved.putString("local",local.toString());if(chosen!=null)saved.putString("offset",chosen.getId());if(seconds!=null)saved.putString("seconds",seconds.getText().toString());if(calendar!=null&&calendar.showing())saved.putBundle("calendar",calendar.state());return saved;}
