    @Override public void finish(){if(saving){Ui.toast(this,"Please wait for this save to finish.");return;}super.finish();}
    // Android 11/12 fallback; Android 13+ uses the platform callback above.
    @android.annotation.SuppressLint("GestureBackNavigation")
    @Override public void onBackPressed(){if(saving){Ui.toast(this,"Please wait for this save to finish.");return;}super.onBackPressed();}
    @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
    void awaitReaders(long timeoutMs)throws Exception {if(worker.isShutdown()){if(!worker.awaitTermination(timeoutMs,TimeUnit.MILLISECONDS))throw new TimeoutException("Record workers still active");}else worker.submit(()->{}).get(timeoutMs,TimeUnit.MILLISECONDS);}
    @Override protected void onDestroy(){handler.removeCallbacks(pollSave);if(timeEditor!=null)timeEditor.close();if(quantityDialog!=null)quantityDialog.dismiss();if(detailSheet!=null)detailSheet.dismiss();if(choiceDialog!=null)choiceDialog.dismiss();worker.shutdown();super.onDestroy();}
